 window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','a','d','w','s'].includes(e.key))e.preventDefault();if(e.repeat)return;if(e.key==='ArrowLeft'||e.key==='a')act('left');if(e.key==='ArrowRight'||e.key==='d')act('right');if(e.key==='ArrowUp'||e.key==='w'||e.key===' ')act('jump');if(e.key==='ArrowDown'||e.key==='s')act('slide');if((e.key==='Enter'||e.key===' ')&&!playing&&overlay.classList.contains('hidden')===false&& !ended)startGame()},{passive:false});
 for(const btn of document.querySelectorAll('.ctrl')){const down=e=>{e.preventDefault();btn.classList.add('pressed');act(btn.dataset.action)};const up=()=>btn.classList.remove('pressed');btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('pointerleave',up)}
 let touchStart=null;renderer.domElement.addEventListener('touchstart',e=>{if(e.touches.length)touchStart=[e.touches[0].clientX,e.touches[0].clientY]},{passive:true});renderer.domElement.addEventListener('touchend',e=>{if(!touchStart||!playing)return;const t=e.changedTouches[0],dx=t.clientX-touchStart[0],dy=t.clientY-touchStart[1];if(Math.abs(dx)>28||Math.abs(dy)>28){if(Math.abs(dx)>Math.abs(dy))act(dx<0?'left':'right');else act(dy<0?'jump':'slide')}touchStart=null},{passive:true});

-const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.035);if(playing){elapsed+=dt;distance+=speed*dt*.72;speed=Math.min(27,17+distance*.006);spawnTimer-=dt;if(spawnTimer<=0){row();spawnTimer=Math.max(.82,1.35-distance*.00045)}if(jumping){player.position.y+=jumpV*dt;jumpV-=22*dt;if(player.position.y<=0){player.position.y=0;jumping=false;jumpV=0}}if(sliding>0)sliding-=dt;const isSlide=sliding>0;avatar.scale.y=THREE.MathUtils.damp(avatar.scale.y,isSlide?.53:1,12,dt);avatar.position.y=isSlide?-.12:0;player.position.x=THREE.MathUtils.damp(player.position.x,lanes[lane],13,dt);const run=elapsed*12;legPivots[0].rotation.x=Math.sin(run)*.72;legPivots[1].rotation.x=-Math.sin(run)*.72;armPivots[0].rotation.x=-Math.sin(run)*.6;armPivots[1].rotation.x=Math.sin(run)*.6;avatar.rotation.z=THREE.MathUtils.damp(avatar.rotation.z,(lanes[lane]-player.position.x)*-.05,8,dt);shadow.position.x=player.position.x;shadow.scale.setScalar(1-player.position.y*.11);for(let i=objects.length-1;i>=0;i--){const o=objects[i];o.position.z+=speed*dt;if(o.userData.spin)o.rotation.y+=dt*2.7;if(o.position.z>3.1){if(o.userData.kind==='obstacle'&&Math.abs(o.position.z-1.5)<1.15&&Math.abs(o.position.x-player.position.x)<1.3){const t=o.userData.type;let safe=(t==='barrier'&&player.position.y>.62)||(t==='desk'&&isSlide)||(t==='gate'&&isSlide)||(t==='cone'&&player.position.y>.48);if(!safe){shake=.3;endGame()}}if(o.userData.kind==='cash'&&Math.abs(o.position.z-1.5)<1.1&&Math.abs(o.position.x-player.position.x)<1){cash+=100;showToast('+$100 CASH!');scene.remove(o);objects.splice(i,1);continue}scene.remove(o);objects.splice(i,1)}}setText();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)toastEl.classList.remove('show')}}
+const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const dt=Math.min(clock.getDelta(),.035);if(playing){elapsed+=dt;distance+=speed*dt*.72;speed=Math.min(27,17+distance*.006);spawnTimer-=dt;if(spawnTimer<=0){row();spawnTimer=Math.max(.82,1.35-distance*.00045)}if(jumping){player.position.y+=jumpV*dt;jumpV-=22*dt;if(player.position.y<=0){player.position.y=0;jumping=false;jumpV=0}}if(sliding>0)sliding-=dt;const isSlide=sliding>0;avatar.scale.y=THREE.MathUtils.damp(avatar.scale.y,isSlide?.53:1,12,dt);avatar.position.y=isSlide?-.12:0;player.position.x=THREE.MathUtils.damp(player.position.x,lanes[lane],13,dt);const run=elapsed*12;legPivots[0].rotation.x=Math.sin(run)*.72;legPivots[1].rotation.x=-Math.sin(run)*.72;armPivots[0].rotation.x=-Math.sin(run)*.6;armPivots[1].rotation.x=Math.sin(run)*.6;avatar.rotation.z=THREE.MathUtils.damp(avatar.rotation.z,(lanes[lane]-player.position.x)*-.05,8,dt);shadow.position.x=player.position.x;shadow.scale.setScalar(1-player.position.y*.11);for(let i=objects.length-1;i>=0;i--){const o=objects[i];o.position.z+=speed*dt;if(o.userData.spin)o.rotation.y+=dt*2.7;const near=Math.abs(o.position.z-1.5)<.72;if(near&&!o.userData.checked&&Math.abs(o.position.x-player.position.x)<1.25){o.userData.checked=true;if(o.userData.kind==='cash'){cash+=100;showToast('+$100 CASH!');scene.remove(o);objects.splice(i,1);continue}if(o.userData.kind==='obstacle'){const t=o.userData.type;const safe=(t==='barrier'&&player.position.y>.62)||(t==='desk'&&isSlide)||(t==='gate'&&isSlide)||(t==='cone'&&player.position.y>.48);if(!safe){shake=.3;endGame()}}}if(o.position.z>5){scene.remove(o);objects.splice(i,1)}}setText();if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)toastEl.classList.remove('show')}}
  // road motion and subtle camera response
  for(const child of scene.children){if(child.userData.dash){child.position.z+=speed*dt;if(child.position.z>14)child.position.z=-112}}
  camera.position.x=THREE.MathUtils.damp(camera.position.x,player.position.x*.13,3,dt);camera.position.y=5.3+Math.sin(elapsed*12)*.035*(playing?1:0);camera.lookAt(player.position.x*.1,1.1,-5);renderer.render(scene,camera)}
